package org.apache.commons.jxpath.ri.model.beans;

import java.io.*;
import java.math.*;
import java.util.*;
import javax.xml.namespace.QName;
import org.apache.commons.jxpath.AbstractFactory;
import org.apache.commons.jxpath.JXPathAbstractFactoryException;
import org.apache.commons.jxpath.JXPathContext;
import org.apache.commons.jxpath.JXPathIntrospector;
import org.apache.commons.jxpath.ri.QName;
import org.apache.commons.jxpath.ri.model.NodePointer;
import org.apache.commons.jxpath.ri.model.beans.NodePointer;
import org.apache.commons.jxpath.ri.model.beans.PropertyPointer;
import org.apache.commons.jxpath.util.ValueUtils;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Spy;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

public class PropertyPointer_createChild_TriageGen1Test {

    @Spy
    private PropertyPointer propertyPointerSpy;

    @Mock
    private JXPathContext mockContext;

    @Mock
    private NodePointer mockResultNodePointer;

    @Mock
    private PropertyPointer mockClonedProp;

    @Before
    public void setUp() {
        // Since PropertyPointer is abstract/complex, we use a spy or mock of the class under test.
        // However, the method calls clone(), which is a protected method of Object.
        // To test the logic inside createChild, we need to handle the clone() behavior.
    }

    /**
     * Test createChild when name is NOT null.
     * Covers the if (name != null) branch.
     */
    @Test
    public void testCreateChild_WithName() throws Exception {
        // We need to mock the clone() behavior. Since clone() is protected, 
        // we use a subclass or a spy that returns a mock PropertyPointer.
        PropertyPointer spyPointer = spy(new TestPropertyPointer(mock(NodePointer.class)));

        QName name = new QName("http://test", "testProperty");
        int index = 5;
        NodePointer expectedResult = mock(NodePointer.class);

        // Mock clone() to return our mockClonedProp
        when(spyPointer.clone()).thenReturn(mockClonedProp);

        // Setup mockClonedProp behavior
        when(mockClonedProp.createPath(mockContext)).thenReturn(expectedResult);

        // Execute
        NodePointer result = spyPointer.createChild(mockContext, name, index);

        // Verify
        verify(mockClonedProp).setPropertyName(name.toString());
        verify(mockClonedProp).setIndex(index);
        verify(mockClonedProp).createPath(mockContext);
        assertEquals(expectedResult, result);
    }

    /**
     * Test createChild when name IS null.
     * Covers the else/skip branch of the if (name != null) condition.
     */
    @Test
    public void testCreateChild_WithNullName() throws Exception {
        PropertyPointer spyPointer = spy(new TestPropertyPointer(mock(NodePointer.class)));

        QName name = null;
        int index = 10;
        NodePointer expectedResult = mock(NodePointer.class);

        when(spyPointer.clone()).thenReturn(mockClonedProp);
        when(mockClonedProp.createPath(mockContext)).thenReturn(expectedResult);

        // Execute
        NodePointer result = spyPointer.createChild(mockContext, name, index);

        // Verify
        // setPropertyName should NOT be called because name is null
        verify(mockClonedProp, org.mockito.Mockito.never()).setPropertyName(any(String.class));
        verify(mockClonedProp).setIndex(index);
        verify(mockClonedProp).createPath(mockContext);
        assertEquals(expectedResult, result);
    }

    /**
     * Concrete implementation for testing purposes to allow instantiation of the abstract class.
     */
    private static class TestPropertyPointer extends PropertyPointer {
        private String propertyName;
        private int index;

        public TestPropertyPointer(NodePointer parent) {
            super(parent);
        }

        @Override
        public void setPropertyName(String propertyName) {
            this.propertyName = propertyName;
        }

        @Override
        public String getPropertyName() {
            return propertyName;
        }

        @Override
        public void setIndex(int index) {
            this.index = index;
        }

        @Override
        public int getPropertyIndex() {
            return index;
        }

        // Implement other abstract methods with dummy values to satisfy compiler/runtime
        @Override public Object getBean() { return null; }
        @Override public QName getName() { return null; }
        @Override public int getPropertyCount() { return 0; }
        @Override public String[] getPropertyNames() { return new String[0]; }
        @Override protected boolean isActualProperty() { return false; }
        @Override public boolean isActual() { return false; }
        @Override public Object getImmediateNode() { return null; }
        @Override public boolean isCollection() { return false; }
        @Override public boolean isLeaf() { return false; }
        @Override public int getLength() { return 0; }
        @Override public NodePointer getImmediateValuePointer() { return null; }
        @Override public NodePointer createPath(JXPathContext context) { return null; }
        @Override public NodePointer createPath(JXPathContext context, Object value) { return null; }
        @Override public NodePointer createChild(JXPathContext context, QName name, int index, Object value) { return null; }
    }
}

// Mocking utility for the test class
class Mock {
    public static <T> T mock(Class<T> classToMock) {
        return org.mockito.Mockito.mock(classToMock);
    }
}
